int main() {
    int k;
    cin >> k;
    char bascic = 'a';
    string res = "";
    while (k != 0) {
        // 转换成0-base
        k -= 1;
        int tmp = k % 26;
        char c = bascic + tmp;
        res = string(1, c) + res;
        k /= 26;
    }
    cout << res;
    return 0;
}

