const readline = require("readline");
​
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
rl.on("line", (line) => {
    let k = parseInt(line.trim(), 10);
    let basic = 'a'.charCodeAt(0);
    let res = [];
​
    while (k !== 0) {
        // 转换成 0-base
        k -= 1;
        let tmp = k % 26;
        res.unshift(String.fromCharCode(basic + tmp));  // 头插法
        k = Math.floor(k / 26);
    }
​
    console.log(res.join(""));
    rl.close();
});
