package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
)
​
func convertToLetters(k int) string {
    basic := 'a'
    res := ""
​
    for k != 0 {
        // 转换成 0-base
        k -= 1
        tmp := k % 26
        res = string(basic+rune(tmp)) + res // 头插法
        k /= 26
    }
    return res
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    k, _ := strconv.Atoi(scanner.Text()) // 读取整数
    fmt.Println(convertToLetters(k))
}
